public UnivariatePointValuePair optimize(int maxEval, UnivariateFunction f,
                                              GoalType goalType,
                                              double min, double max,
                                              double startValue) {
    // Checks.
    if (f == null) {
        throw new NullArgumentException();
    }
    if (goalType == null) {
        throw new NullArgumentException();
    }
    if (min >= max) {
        throw new NumberIsTooLargeException(min, max, false);
    }
    if (startValue < min || startValue > max) {
        throw new OutOfRangeException(startValue, min, max);
    }
    // Reset.
    searchMin = min;
    searchMax = max;
    searchStart = startValue;
    goal = goalType;
    function = f;
    evaluations.setMaximalCount(maxEval);
    evaluations.resetCount();
    // Perform computation.
    return doOptimize();
}

public static UnivariateFunction add(final UnivariateFunction ... f) {
    return new UnivariateFunction() {
        /** {@inheritDoc} */
        public double value(double x) {
            double r = f[0].value(x);
            for (int i = 1; i < f.length; i++) {
                r += f[i].value(x);
            }
            return r;
        }
    };
}

